'use strict';
let questions=[
{m:0,title:'Wer spricht für wen?',e:'Die Frau wählt ein Gericht und nennt es dem Mann. Er gibt die Bestellung an den Kellner weiter.',q:'Welche soziale Rollenerwartung wird hier sichtbar?',a:['Der Mann vertritt die Frau im Gespräch mit dem Service.','Alle Gäste müssen ihre Bestellung schriftlich abgeben.','Die Frau darf grundsätzlich kein Gericht auswählen.'],c:0,f:'Der Text erlaubt der Frau die Auswahl, erwartet aber die Vermittlung durch den Mann. Die soziale Rolle betrifft hier das Auftreten gegenüber dem Service.'},
{m:0,title:'Wert oder Norm?',e:'Wer den Kellner rufen möchte, soll dies durch ein Zeichen oder leichtes Winken tun. Lautes Rufen gilt als ungehörig.',q:'Welche Zuordnung ist fachlich am treffendsten?',a:['Winken ist ein Wert; Höflichkeit ist eine Norm.','Höflichkeit ist ein möglicher Wert; dezentes Winken ist eine konkrete Norm.','Winken ist eine gesetzliche Pflicht.'],c:1,f:'Werte sind allgemeine Leitvorstellungen. Normen formulieren konkrete Verhaltenserwartungen. Höflichkeit lässt sich als möglicher zugrunde liegender Wert erschließen.'},
{m:0,title:'Die unsichtbare Sanktion',e:'Lautes Rufen oder auffälliges Klopfen am Glas wird als schlechtes Benehmen bewertet.',q:'Welche Sanktion liegt hier am ehesten nahe?',a:['Eine automatisch verhängte Geldstrafe.','Ein gesetzliches Verbot des Cafébesuchs.','Soziale Missbilligung, etwa ein tadelnder Blick.'],c:2,f:'Die Regel bewertet das Verhalten negativ. Missbilligung ist eine mögliche informelle Sanktion; eine tatsächliche Reaktion beschreibt der Auszug nicht.'},
{m:1,title:'Ein freundliches Machtgefälle?',e:'Der Mann sucht einen Tisch aus und fragt, ob die Frau einverstanden ist. Er übernimmt außerdem das Bezahlen.',q:'Welche Analyse berücksichtigt beide Seiten?',a:['Fürsorge und eine ungleiche Verteilung von Entscheidungsmacht können gleichzeitig vorliegen.','Die Frage nach Zustimmung beweist vollständige Gleichberechtigung in allen Bereichen.','Bezahlen allein beweist, dass die Frau keine eigenen Wünsche hat.'],c:0,f:'Die Zustimmung wird erfragt; zugleich übernimmt der Mann zentrale Aufgaben. Eine differenzierte Analyse erkennt beides, ohne aus einer Einzelregel alles über die Beteiligten abzuleiten.'},
{m:1,title:'Nicht jede Regel gilt für alle',e:'Ein Restaurant oder Café darf ein junges Mädchen allein besuchen; ein Tanzlokal oder eine Bar hingegen laut Text niemals allein.',q:'Was lässt sich aus dem Material ableiten?',a:['Frauen durften nach diesem Text überhaupt nicht allein ausgehen.','Die Regeln unterscheiden nach Ort und richten sich gezielt an junge Mädchen.','Diese Regeln gelten heute gesetzlich für alle Jugendlichen.'],c:1,f:'Der Text macht eine konkrete Unterscheidung. Er zeigt geschlechts- und altersbezogene Erwartungen, belegt aber weder heutige Gesetze noch das tatsächliche Verhalten aller Menschen damals.'},
{m:1,title:'Die Falle mit dem Jahr',e:'Auf Buchseite 176 wird das ursprüngliche Jahr des Benimmbuchs zur Frage gestellt. Die Café-Bilder im Spiel wurden mit KI erstellt.',q:'Welche Aussage ist quellenkritisch korrekt?',a:['Die Bilder zeigen sicher das Entstehungsjahr.','Die Regeln stammen nachweislich aus dem Jahr 1900.','Das ursprüngliche Jahr bleibt offen; die Illustration ist kein Datierungsbeleg.'],c:2,f:'Das Material lässt das ursprüngliche Jahr offen. Eine nachträglich erzeugte Illustration liefert keinen Datierungsbeleg.'},
{m:2,title:'Wie Rollen gelernt werden',e:'Das Benimmbuch erklärt jungen Mädchen, welches Verhalten in verschiedenen Situationen erwartet wird.',q:'Welcher Fachbegriff passt zu dieser Funktion?',a:['Sozialisation: gesellschaftliche Erwartungen werden vermittelt.','Biologie: die Regeln werden angeboren.','Inflation: Geld verliert seinen Wert.'],c:0,f:'Ein Ratgeber kann an Sozialisation mitwirken, indem er Werte, Normen und Rollen vermittelt. Menschen können solche Erwartungen übernehmen, verändern oder ablehnen.'},
{m:2,title:'Neue Szene, neue Absprache',e:'Heute im Café: Zwei Personen sprechen vorher ab, dass eine einlädt. Beide bestellen selbst und entscheiden gemeinsam über den Tisch.',q:'Was unterscheidet diese Absprache von der Regel im Material?',a:['Wer bezahlt, muss immer für beide bestellen.','Die Aufgaben werden ausgehandelt und nicht automatisch dem Geschlecht zugeordnet.','Es gibt heute überhaupt keine sozialen Normen mehr.'],c:1,f:'Eine freiwillige Einladung kann mit Selbstbestimmung vereinbar sein. Entscheidend ist hier die Aushandlung statt einer festen geschlechtsbezogenen Pflicht. Auch heutige Cafés kennen Normen.'},
{m:2,title:'Dein Urteil braucht Gründe',e:'Im Material soll die Frau die Verhandlungen mit dem Kellner nicht selbst führen.',q:'Welche Beurteilung verbindet Kriterium und Materialbeleg?',a:['Die Regel ist schlecht, weil alte Texte immer falsch sind.','Die Regel ist gut, weil Regeln niemals hinterfragt werden sollten.','Gemessen an Selbstbestimmung ist die Regel problematisch, weil sie das selbstständige Auftreten der Frau einschränkt.'],c:2,f:'Ein begründetes Urteil nennt ein Kriterium und bezieht es auf einen konkreten Beleg. Historischen Kontext zu berücksichtigen heißt nicht, die Norm übernehmen zu müssen.'}
];

