function renderStory(){const s=state.story;const panelNode=panel(3,'Die Café-Bühne: Eure neue Ordnung','Drei Entscheidungen verändern das Café. Mehrere Wege sind vertretbar; die Rückmeldungen untersuchen ihre Folgen.','together');if(s.pos<story.length){const scene=story[s.pos];if(!s.recalled.includes(s.pos)){panelNode.append(el('h3',scene.title),el('p','Die Café-Bühne bleibt im historischen Rollenbild stehen. Setze den Kristall in den Erinnerungssockel und aktiviere die Spur '+['Tischwahl','Bestellung','Bezahlen'][s.pos]+'. Vergleicht danach eure Lösung mit dem Material.'));const socket=button('Kristall in den Sockel setzen',()=>{if(!state.tools.crystal){panelNode.append(live('Wähle zuerst den Erinnerungskristall im Inventar und setze ihn ein.'));return;}openCrystal();},'roomMechanism');socket.append(asset('crystal','Kristall im Erinnerungssockel'));$('roomCanvas').append(socket);return;}panelNode.append(el('p',`Szene ${s.pos+1}/3`,'eyebrow'),el('h3',scene.title),el('p',scene.text),el('p','Bezug zu Buchseite 176: '+['Im Ausgangstext übernimmt der männliche Begleiter die Tischwahl und fragt nach Zustimmung.','Im Ausgangstext wählt die Frau ihr Gericht; die Bestellung wird durch den männlichen Begleiter vermittelt.','Im Ausgangstext wird dem männlichen Begleiter das Bezahlen zugewiesen.'][s.pos],'materialAnchor'));const choices=el('div',undefined,'storyChoices');scene.a.forEach(([choice,why],n)=>{const b=button(choice,()=>{if(s.choices[s.pos]!==undefined)return;s.choices[s.pos]=n;record('Café-Entscheidung',scene.title+': '+choice+' · '+why);renderStory();$('activityBody').querySelector('button.primary')?.focus({preventScroll:true});},'choice');b.disabled=s.choices[s.pos]!==undefined;if(s.choices[s.pos]===n)b.classList.add('correct');choices.append(b);});panelNode.append(choices);if(s.choices[s.pos]!==undefined){panelNode.append(live(scene.a[s.choices[s.pos]][1]),button('Nächste Szene ',()=>{s.pos++;renderStory();focusHeading();},'primary'));}}else{panelNode.append(el('h3','Formuliert ein begründetes Urteil'),el('p','Nennt einen Wert, eine konkrete Entscheidung und einen möglichen Einwand. Vergleicht eure neue Ordnung mit Buchseite 176.'));const label=el('label','Euer Urteil (keine automatische Bewertung)');label.htmlFor='storyReflection';const input=el('textarea');input.id='storyReflection';input.rows=5;input.value=s.judgment;input.placeholder='Gemessen an … ist unsere Entscheidung …, weil … Ein möglicher Einwand ist …';input.oninput=()=>s.judgment=input.value;panelNode.append(label,input,el('p','Keine Namen oder persönlichen Informationen eingeben. Ein leeres Urteil kann im Unterricht mündlich besprochen werden.','sourceNote'));if(!s.confirmed)panelNode.append(button('Urteil festhalten und Siegel prüfen',()=>{s.confirmed=true;record('Urteil festgehalten',s.judgment||'Offen: mündliche Besprechung vorgesehen');renderStory();},'primary'));if(s.confirmed&&!s.seal){const box=el('div',undefined,'sealBox');box.append(el('h3','Das Siegel der Selbstbestimmung'),el('p','Welche Begründung ist differenziert?'));['Eine feste Geschlechterregel ist gerecht, weil sie immer galt.','Eine freiwillig ausgehandelte Einladung kann mit Gleichberechtigung vereinbar sein.','Gleichberechtigung bedeutet, dass es keinerlei Regeln mehr gibt.'].forEach((text,n)=>box.append(button(text,()=>{s.sealAttempts++;record('Begründungssiegel',text);s.last=n===1?'Kriterium und freiwillige Absprache passen zusammen.':'Prüfe Freiwilligkeit, eigene Wünsche und konkrete Regeln.';if(n===1)s.seal=true;renderStory();},'choice')));panelNode.append(box);if(s.last)panelNode.append(live(s.last));}if(s.seal)completePanel(panelNode,3,'Die Café-Ordnung ist wieder handlungsfähig. Der Schlüssel aktiviert nun die Zeittür.');}tools(panelNode);}
function renderDoor(){$('activity').classList.remove('memoryMode');show('door');currentRoom=3;$('roomName').textContent='Die Ausgangstür';$('roomSubtitle').textContent='Verknüpfe eure Erkenntnisse';$('roomImage').src='assets/room-stage.png';$('roomCanvas').replaceChildren();$('activityBody').replaceChildren();const panelNode=el('article',undefined,'activityPanel');$('activityBody').append(panelNode);if(!state.final.turned){panelNode.append(el('h2','Die Tür ist verriegelt'),el('p','Setze den Schlüssel aus dem Inventar am Schloss ein.'));panelNode.append(el('p',!state.tools.key?'1. Schlüssel im Inventar wählen. 2. Am Schlüsselloch einsetzen. 3. Drehen.':state.final.inserted?'Der Schlüssel steckt. Drehe ihn, um die Schlossringe freizugeben.':'Schlüssel ausgerüstet. Klicke jetzt das Schlüsselloch im Raum.'));const lock=button('',()=>{if(!state.tools.key){panelNode.append(live('Rüste zuerst den Schlüssel über das Inventar aus.'));return;}if(!state.final.inserted){state.final.inserted=true;record('Schlüssel eingesteckt','Am Schlüsselloch der Ausgangstür');}else{state.final.turned=true;record('Schlüssel gedreht','Schlossringe freigegeben');}renderDoor();},'doorKey');lock.append(asset('key','Schlüssel am Türschloss'),el('span',state.final.inserted?'Schlüssel drehen':'Schlüsselloch · Schlüssel einsetzen'));$('roomCanvas').append(lock);return;}const f=state.final;if(f.pos<4){const r=finalRiddles[f.pos];panelNode.append(el('h2',`Schlossring ${f.pos+1} von 4`),el('p',r.q));const options=el('div',undefined,'sortOptions');categories.forEach(cat=>{const b=button(cat,()=>{f.choices[f.pos]=cat;renderDoor();},'choice');b.setAttribute('aria-pressed',f.choices[f.pos]===cat?'true':'false');if(f.choices[f.pos]===cat)b.classList.add('selected');options.append(b);});panelNode.append(options,button('Verbindung prüfen',()=>{f.attempts++;if(f.choices[f.pos]!==r.c){f.last=r.why;record('Türschloss','Verbindung noch nicht passend');}else{record('Türschloss','Schlossring '+(f.pos+1)+' verbunden: '+r.c);f.pos++;f.last='';}renderDoor();},'primary'));if(f.last)panelNode.append(live(f.last));panelNode.append(button('Kompass zur Orientierung',()=>useItem(1)));}else{panelNode.append(el('h2','Das letzte Schloss'),el('p','Übersetze die vier verbundenen Begriffe in Zahlen. Der Kompass zeigt das Zahlenrad.'),el('p',f.choices.join(' · '),'codeSequence'));const label=el('label','Vierstelliger Türcode');label.htmlFor='finalCode';const input=el('input');input.id='finalCode';input.inputMode='numeric';input.maxLength=4;input.value=f.code||'';input.oninput=()=>f.code=input.value;panelNode.append(label,input,button('Tür öffnen',()=>{f.attempts++;if(f.code!=='2358'){f.last='Nutze die Zahlen auf dem Kompass in der Reihenfolge der verbundenen Begriffe.';record('Türcode','Noch nicht passend');renderDoor();return;}state.escaped=true;state.ended=new Date().toISOString();state.endTick=performance.now();record('Escape abgeschlossen','Materialbezüge verknüpft und Café verlassen');renderEscaped();},'primary'),button('Kompass einsetzen',()=>useItem(1)));if(f.last)panelNode.append(live(f.last));}animateTask(panelNode,4);}
function renderEscaped(){show('escaped');$('escapeSummary').replaceChildren(el('p','Ihr habt Rollen untersucht, Bildspuren kritisch gedeutet, Café-Regeln rekonstruiert und Entscheidungen begründet.'),el('p','Abschluss: '+stamp(state.ended)),el('p','Dauer: '+duration()));$('escaped').tabIndex=-1;$('escaped').focus();}
function duration(){if(!state.started)return '0 Min. 0 Sek.';const sec=Math.max(0,Math.floor(((state.endTick??performance.now())-state.startTick)/1000));return `${Math.floor(sec/60)} Min. ${sec%60} Sek. (einschließlich Pausen)`;}
function summaryLines(){return ['CAFÉ DER ROLLEN — LERNPROTOKOLL','Buchseite 176 · eigene Zusammenfassungen und fiktive Transferbeispiele','Status: '+(state.escaped?'Escape abgeschlossen':state.started?'Zwischenstand':'Noch nicht gestartet'),'Rundenstart: '+(state.started?stamp(state.started):'noch nicht gestartet'),'Abschluss: '+(state.ended?stamp(state.ended):'noch nicht abgeschlossen'),'Dauer: '+duration(),'Erstellt: '+stamp(new Date()),'Zeitbasis: Geräteuhr. Kein manipulationssicherer Nachweis.','', 'KURZÜBERSICHT',...rooms.map((room,n)=>`${n+1}. ${room}: ${state.done[n]?'abgeschlossen':'offen'}`),`Archiv: ${state.quiz.answers.filter(a=>a.correct).length}/${state.quiz.answers.length} beantwortete Erstversuche richtig; ${state.quiz.tpos}/${state.quiz.transfer.length} erforderliche Transferfragen gelöst.`,`Werkstatt: ${state.sort.solved.filter(a=>a.first).length}/${state.sort.solved.length} im Erstversuch richtig; ${state.sort.attempts.length-state.sort.solved.length} Fehlversuche.`,`Bildlabor: ${state.visual.solved.length}/2 Szenen geklärt; ${state.visual.attempts.filter(a=>!a.correct).length} Fehlversuche.`,`Memory: ${state.memory.matched.length}/6 Paare; ${state.memory.tries} Versuche.`,`Bühne: ${state.story.choices.length}/3 Entscheidungen; ${state.story.sealAttempts} Siegelversuche.`,`Türschloss: ${state.final.attempts} Versuche · ${state.hints} Hinweise genutzt.`,'','EIGENE URTEILE (NICHT AUTOMATISCH BEWERTET)','Vorbereitung: '+(state.reading.second?'Zweimal vollständig gelesen (Selbstauskunft)':'Lektüre noch nicht vollständig bestätigt'),'Café-Bühne: '+(state.story.judgment||'(offen / mündlich besprechen)'),'','Keine Datenübertragung. Dieses Protokoll enthält eure Antworten und Urteile; nur bewusst weitergeben.'];}
function reportText(){return [...summaryLines(),'','CHRONOLOGISCHER VERLAUF (ISO-ZEITSTEMPEL UTC)',...state.events.map((e,i)=>`${i+1}. ${stamp(e.at)} | ${e.at}\n${e.type}: ${e.detail}`)].join('\n');}
function saveText(text,name){const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'}));const a=el('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadProtocol(){saveText(reportText(),'Cafe-Lernprotokoll-'+new Date().toISOString().replace(/[:.]/g,'-')+'.txt');}
let currentRoom=0,travelBusy=false,lastRoom=0,lastTask='',mapPosition=null;const mapPoints=[[27,26],[76,26],[76,73],[26,73]];
function asset(name,alt=''){const img=el('img');img.src='assets/item-'+name+'.png';img.alt=alt;img.draggable=false;return img;}
function motionEnabled(){return !matchMedia('(prefers-reduced-motion: reduce)').matches;}
function animateTask(node,n){const key=n+':'+(n===0?state.quiz.pos+'/'+state.quiz.tpos:n===1?state.visual.pos+'/'+state.sort.pos:n===3?state.story.pos:n===4?state.final.pos:'memory');if(key!==lastTask&&motionEnabled())node.animate([{opacity:0,transform:'translateX(12px)'},{opacity:1,transform:'translateX(0)'}],{duration:380,easing:'ease-out'});lastTask=key;}
async function travel(n,back,action){
 if(travelBusy)return;
 if(!motionEnabled()){if(!back)mapPosition=n;action();return;}
 travelBusy=true;
 const overlay=$('cameraTransition'),picture=$('cameraImage');
 const station=state.page==='map'&&!back?document.querySelector(action===renderDoor?'#exitDoor':'.station'+n):null;
 if(!back&&state.page!=='map')mapPosition=n;const destination=back?'assets/cafe-map.png':'assets/room-'+['archive','workshop','memory','stage'][n]+'.png';
 const destinationName=back?'Café-Karte':action===renderDoor?'Ausgang':rooms[n];
 overlay.classList.toggle('toMap',back);
 overlay.classList.remove('doorOpened');
 $('cameraTitle').textContent=destinationName;
 $('transitionStep').textContent=back?'Zurück zur Übersicht':action===renderDoor?'Das letzte Schloss':'Raum '+(n+1)+' von 4 · Eintreten';
 const animations=[];
 const play=async(node,frames,options)=>{const animation=node.animate(frames,options);animations.push(animation);await animation.finished;};
 try{
  picture.src=destination;
  await picture.decode().catch(()=>{});
  if(station){const traveller=$('mapTraveller');const target=action===renderDoor?[50,35]:mapPoints[n];const origin=mapPosition===null?[50,89]:mapPoints[mapPosition];await play(traveller,[{left:origin[0]+'%',top:origin[1]+'%'},{left:'50%',top:'50%',offset:.45},{left:target[0]+'%',top:target[1]+'%'}],{duration:1250,easing:'ease-in-out',fill:'forwards'});mapPosition=n;}if(station)await play(station,[{boxShadow:'0 0 0 0px #fff2bc00'},{boxShadow:'0 0 0 8px #fff2bcbb',background:'#fff0bb'}],{duration:260,easing:'ease-out',fill:'forwards'});
  overlay.hidden=false;
  await play(overlay,[{opacity:0},{opacity:1}],{duration:300,easing:'ease-in-out',fill:'forwards'});
  if(!back){
   $('transitionStep').textContent='Die Tür öffnet sich';
   const left=overlay.querySelector('.doorLeafLeft'),right=overlay.querySelector('.doorLeafRight');
   await Promise.all([
    play(left,[{transform:'rotateY(0deg)'},{transform:'rotateY(-100deg)'}],{duration:950,easing:'cubic-bezier(.3,0,.2,1)',fill:'forwards'}),
    play(right,[{transform:'rotateY(0deg)'},{transform:'rotateY(100deg)'}],{duration:950,easing:'cubic-bezier(.3,0,.2,1)',fill:'forwards'})
   ]);
   overlay.classList.add('doorOpened');
  }
  action();
  await play(overlay,[{opacity:1},{opacity:0}],{duration:320,easing:'ease-out',fill:'forwards'});
 }finally{
  overlay.hidden=true;
  animations.forEach(animation=>animation.cancel());
  overlay.classList.remove('doorOpened');
  travelBusy=false;
 }
}

function enter(n){if(!state.reading.second)return;if(n>0&&!state.done[n-1])return;lastRoom=n;travel(n,false,()=>enterImmediately(n));}
