function openCrystal(){const popup=$('toolPopup');popup.replaceChildren();popup.hidden=false;const close=button('Schließen',()=>popup.hidden=true,'toolClose');popup.append(close,el('h3','Erinnerungskristall'));const crystal=el('div',undefined,'crystalInstrument');crystal.append(asset('crystal','KI-generierter Erinnerungskristall'));const memories=['Tischwahl: Der männliche Begleiter sucht einen Tisch und fragt nach Zustimmung. Prüft, wie echte Mitbestimmung möglich ist.','Bestellung: Die Frau wählt ihr Gericht, der männliche Begleiter spricht mit dem Service. Prüft Auswahl und eigenes Auftreten getrennt.','Bezahlen: Das Bezahlen wird dem Mann zugewiesen. Prüft den Unterschied zwischen fester Rollenerwartung und freiwilliger Einladung.'];memories.forEach((text,i)=>crystal.append(button(['Tischwahl','Bestellung','Bezahlen'][i],()=>{$('crystalMemory').textContent=text;record('Kristallspur gelesen',['Tischwahl','Bestellung','Bezahlen'][i]);if(state.page==='story'&&state.story.pos<3){if(i===state.story.pos){if(!state.story.recalled.includes(i))state.story.recalled.push(i);record('Bühnenbild freigeschaltet',story[i].title);const continueButton=button('Spur übernehmen – Szene gestalten',()=>{popup.hidden=true;renderStory();},'primary');popup.querySelector('.primary')?.remove();popup.append(continueButton);}else $('crystalMemory').textContent=text+' Diese Spur gehört zu einer anderen Szene. Gesucht: '+['Tischwahl','Bestellung','Bezahlen'][state.story.pos]+'.';}},'crystalShard shard'+i)));popup.append(crystal,live('Berühre eine Kristallspur, um einen Materialbezug sichtbar zu machen.'));popup.lastChild.id='crystalMemory';close.focus({preventScroll:true});}
function revealZone(buttonNode){if(state.tools.loupe){if(!buttonNode.classList.contains('revealed'))record('Lupenspur enthüllt',buttonNode.getAttribute('aria-label'));buttonNode.classList.add('revealed');}}
function attachLens(frame){frame.classList.add('loupeActive');const lens=el('div',undefined,'magnifierLens');lens.setAttribute('aria-hidden','true');const glass=el('div',undefined,'lensGlass');glass.style.backgroundImage='url("assets/order.png")';lens.append(glass,asset('loupe',''));frame.append(lens);const position=(x,y)=>{const rect=frame.getBoundingClientRect();x=Math.max(0,Math.min(rect.width,x));y=Math.max(0,Math.min(rect.height,y));lens.style.left=x+'px';lens.style.top=y+'px';glass.style.backgroundSize=rect.width*2+'px '+rect.height*2+'px';glass.style.backgroundPosition=(glass.clientWidth/2-x*2)+'px '+(glass.clientHeight/2-y*2)+'px';};frame.onpointermove=e=>{const rect=frame.getBoundingClientRect();position(e.clientX-rect.left,e.clientY-rect.top);frame.querySelectorAll('.imageZone').forEach(z=>{const r=z.getBoundingClientRect();if(e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom)revealZone(z);});};frame.querySelectorAll('.imageZone').forEach(z=>{z.onfocus=()=>{revealZone(z);const f=frame.getBoundingClientRect(),r=z.getBoundingClientRect();position(r.left-f.left+r.width/2,r.top-f.top+r.height/2);};z.onpointerdown=()=>revealZone(z);});requestAnimationFrame(()=>position(frame.clientWidth*.5,frame.clientHeight*.4));}
