// Reveal text without changing its accessible name, layout, or answer content.
const typewriterSeen=new Map();
let typewriterJobs=[],typewriterFrame=0,typewriterObserver;
function typingScope(node){return node.closest('dialog')||node.closest('#toolPopup')||node.closest('#activityBody')||node.closest('#roomCanvas')||node.closest('#hub')||node.closest('#intro')||node.closest('#escaped')||node.closest('header')||node.closest('#inventoryDock')||node.closest('#cameraTransition');}
function finishTyping(){
 typewriterJobs.forEach(job=>job.glyphs.forEach(glyph=>glyph.classList.add('typed')));
 typewriterJobs=[];
 cancelAnimationFrame(typewriterFrame);typewriterFrame=0;
}
function typewriterTick(now){
 typewriterJobs=typewriterJobs.filter(job=>{if(!job.run.isConnected)return false;if(!job.run.getClientRects().length){job.glyphs.forEach(glyph=>glyph.classList.add('typed'));return false;}return true;});
 const scopes=new Set();
 typewriterJobs.forEach(job=>{
  if(scopes.has(job.scope))return;
  scopes.add(job.scope);
  if(job.started===null)job.started=now;
  const count=Math.min(job.glyphs.length,Math.floor((now-job.started)/job.delay)+1);
  for(let i=job.shown;i<count;i++)job.glyphs[i].classList.add('typed');
  job.shown=count;
 });
 typewriterJobs=typewriterJobs.filter(job=>job.shown<job.glyphs.length);
 typewriterFrame=typewriterJobs.length?requestAnimationFrame(typewriterTick):0;
}
function scanTypewriter(){
 typewriterObserver?.disconnect();
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
 const texts=[];let node;
 while((node=walker.nextNode())){
  if(!node.textContent.trim()||node.parentElement.closest('.typeRun,script,style,textarea,input,option,.hiddenClue'))continue;
  const scope=typingScope(node.parentElement);
  if(!scope||!node.parentElement.getClientRects().length||node.parentElement.closest('[hidden]'))continue;
  texts.push({node,scope});
 }
 texts.forEach(({node,scope})=>{
  const full=node.textContent;
  const scopeKey=scope.id||scope.tagName;
  if(!typewriterSeen.has(scopeKey))typewriterSeen.set(scopeKey,new Set());
  const seen=typewriterSeen.get(scopeKey),repeat=seen.has(full);
  seen.add(full);
  const run=document.createElement('span');run.className='typeRun';
  const glyphs=Array.from(full).map(char=>{const glyph=document.createElement('span');glyph.className='typeGlyph';glyph.textContent=char;run.append(glyph);return glyph;});
  node.replaceWith(run);
  if(repeat||!motionEnabled()){glyphs.forEach(glyph=>glyph.classList.add('typed'));return;}
  typewriterJobs.push({scope,run,glyphs,started:null,shown:0,delay:Math.min(22,1800/Math.max(1,glyphs.length))});
 });
 typewriterObserver?.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['hidden','open']});
 if(typewriterJobs.length&&!typewriterFrame)typewriterFrame=requestAnimationFrame(typewriterTick);
}
let typewriterScanQueued=false;
typewriterObserver=new MutationObserver(()=>{if(typewriterScanQueued)return;typewriterScanQueued=true;queueMicrotask(()=>{typewriterScanQueued=false;scanTypewriter();});});
const showTextButton=button('Texte sofort anzeigen',finishTyping,'quiet');showTextButton.id='showTextNow';document.querySelector('header nav').append(showTextButton);
document.addEventListener('keydown',event=>{if(event.key==='Escape')finishTyping();});
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',event=>{if(event.matches)finishTyping();});
scanTypewriter();
